CREATE DATABASE IF NOT EXISTS cineplanet;

USE cineplanet;

CREATE TABLE IF NOT EXISTS filmes (
  id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  titulo VARCHAR(200) NOT NULL UNIQUE,
  generos VARCHAR(200) NOT NULL,
  duracao VARCHAR(40) NOT NULL,
  sinopse TEXT NOT NULL,
  imagem VARCHAR(255) NOT NULL,
  ano SMALLINT NULL,
  diretor VARCHAR(200) NULL,
  classificacao VARCHAR(20) NULL,
  nota_imdb DECIMAL(2,1) NULL
);
 -- ignore into evita duplicar pos recarga novamente
