-- As notas IMDb podem mudar; a classificação indicada aqui segue o padrão dos EUA.
UPDATE filmes SET ano=2019, diretor='Anthony Russo, Joe Russo', classificacao='PG-13', nota_imdb=8.4, sinopse='Após uma derrota devastadora, os heróis que restaram precisam encontrar uma forma de reparar as perdas e trazer esperança de volta ao universo. A missão reúne antigos aliados e coloca à prova a coragem, a amizade e os sacrifícios de cada um.' WHERE titulo='Vingadores: Ultimato';
UPDATE filmes SET ano=1993, diretor='Steven Spielberg', classificacao='PG-13', nota_imdb=8.2, sinopse='Um parque temático criado para exibir dinossauros recriados a partir de material genético recebe visitantes antes de estar totalmente pronto. Quando os sistemas de segurança falham, especialistas e crianças precisam atravessar o local e encontrar uma saída enquanto os animais circulam livremente.' WHERE titulo='Jurassic Park';
UPDATE filmes SET ano=2022, diretor='James Cameron', classificacao='PG-13', nota_imdb=7.5, sinopse='Jake e Neytiri construíram uma vida em Pandora e agora precisam proteger seus filhos quando uma antiga ameaça retorna. Para encontrar abrigo, a família se aproxima de um povo ligado ao oceano, aprende seus costumes e enfrenta perigos que colocam em risco tanto seu lar quanto a comunidade que os acolheu.' WHERE titulo='Avatar: O Caminho da Água';
UPDATE filmes SET ano=1997, diretor='James Cameron', classificacao='PG-13', nota_imdb=8.0, sinopse='Durante a viagem inaugural do Titanic, Rose, uma jovem presa às expectativas da alta sociedade, conhece Jack, um artista de origem humilde. A relação entre os dois desafia as diferenças sociais e se desenvolve enquanto o navio segue em direção a um desastre que mudará suas vidas.' WHERE titulo='Titanic';
UPDATE filmes SET ano=1999, diretor='David Fincher', classificacao='R', nota_imdb=8.8, sinopse='Cansado de uma rotina sem sentido e afetado pela insônia, um funcionário conhece Tyler Durden, um homem que rejeita as convenções sociais. Juntos, eles criam encontros clandestinos de luta que atraem cada vez mais participantes e acabam tomando um rumo imprevisível.' WHERE titulo='Clube da Luta';
UPDATE filmes SET ano=2016, diretor='Mel Gibson', classificacao='R', nota_imdb=8.1, sinopse='Inspirado na história real de Desmond Doss, o filme acompanha um médico do Exército que se recusa a portar armas por convicção pessoal. Durante a Batalha de Okinawa, ele permanece no campo de combate para socorrer soldados feridos, mesmo diante de um risco extremo.' WHERE titulo='Até o Último Homem';
UPDATE filmes SET ano=2016, diretor='Tim Miller', classificacao='R', nota_imdb=8.0, sinopse='Depois de ser submetido a um experimento que altera seu corpo, Wade Wilson adota uma identidade irreverente e ganha uma capacidade extraordinária de se recuperar. Enquanto tenta acertar contas com quem destruiu sua vida, ele atravessa situações violentas com humor ácido e pouca preocupação com regras.' WHERE titulo='Deadpool';
UPDATE filmes SET ano=2023, diretor='Aaron Horvath, Michael Jelenic, Pierre Leduc', classificacao='PG', nota_imdb=7.0, sinopse='Os encanadores Mario e Luigi são separados depois de chegar a um reino fantástico, onde Mario conhece novos aliados e aprende a lidar com desafios bem diferentes dos que conhece. Com a ajuda da Princesa Peach e de Toad, ele parte para impedir os planos de Bowser e reencontrar o irmão.' WHERE titulo='Super Mario Bros. O Filme';
UPDATE filmes SET ano=2021, diretor='Adam Wingard', classificacao='PG-13', nota_imdb=6.3, sinopse='Enquanto humanos investigam uma região misteriosa ligada à origem dos Titãs, Godzilla e Kong entram em rota de colisão. A disputa entre os dois gigantes revela uma ameaça maior e obriga diferentes personagens a reconsiderar o que sabem sobre as criaturas e sobre o passado da Terra.' WHERE titulo='Godzilla vs. Kong';
UPDATE filmes SET ano=2017, diretor='Brian Fee', classificacao='G', nota_imdb=6.7, sinopse='Relâmpago McQueen enfrenta uma geração de carros mais velozes e equipados com novas tecnologias, e uma derrota o faz questionar o futuro nas pistas. Com o apoio da treinadora Cruz Ramirez, ele trabalha para recuperar a confiança e descobrir como continuar competitivo sem abandonar sua própria trajetória.' WHERE titulo='Carros 3';
UPDATE filmes SET ano=2017, diretor='Taika Waititi', classificacao='PG-13', nota_imdb=7.9, sinopse='Longe de Asgard e preso no planeta Sakaar, Thor precisa encontrar um caminho de volta antes que Hela consolide seu poder. Para impedir a destruição de seu reino, ele reúne aliados improváveis e encara desafios que o obrigam a repensar o que significa ser um herói.' WHERE titulo='Thor: Ragnarok';
UPDATE filmes SET ano=2013, diretor='Mikael Håfström', classificacao='R', nota_imdb=6.7, sinopse='Ray Breslin, especialista em testar a segurança de prisões, é enganado e enviado para uma instalação praticamente impossível de escapar. Sem poder confiar nos próprios conhecimentos sobre o lugar, ele precisa colaborar com outro detento para descobrir como sair e quem armou sua captura.' WHERE titulo='Rota de Fuga';
UPDATE filmes SET ano=2001, diretor='Andrew Adamson, Vicky Jenson', classificacao='PG', nota_imdb=7.9, sinopse='Quando criaturas de contos de fadas são expulsas de suas casas, o ogro Shrek faz um acordo para recuperar a tranquilidade de seu pântano. Acompanhado pelo falante Burro, ele parte para resgatar a Princesa Fiona e acaba descobrindo que a aventura mudará sua visão sobre amizade e aparência.' WHERE titulo='Shrek';
UPDATE filmes SET ano=2021, diretor='Jon Watts', classificacao='PG-13', nota_imdb=8.1, sinopse='Depois que sua identidade se torna pública, Peter Parker procura uma solução para recuperar a privacidade e proteger as pessoas próximas. Um feitiço que sai do controle abre passagem para visitantes de outros universos e transforma sua tentativa de voltar à vida normal em uma escolha de grandes consequências.' WHERE titulo='Homem-Aranha: Sem Volta Para Casa';
UPDATE filmes SET ano=NULL, diretor=NULL, classificacao=NULL, nota_imdb=NULL, sinopse='Ainda não foi possível identificar o título e os dados deste filme pelo cartaz disponível. As informações serão preenchidas quando o filme for identificado.' WHERE titulo='Filme sem identificação';
UPDATE filmes SET ano=2025, diretor='Jared Hess', classificacao='PG', nota_imdb=5.6, sinopse='Quatro pessoas são levadas por um portal a um mundo cúbico onde a imaginação interfere diretamente no que é possível construir. Com a ajuda de um especialista local, elas precisam aprender a sobreviver, enfrentar perigos e encontrar uma maneira de voltar para casa.' WHERE titulo='Um Filme Minecraft';
UPDATE filmes SET ano=2010, diretor='Lee Unkrich', classificacao='G', nota_imdb=8.3, sinopse='Com Andy prestes a sair de casa para a faculdade, Woody e os outros brinquedos tentam entender qual será seu próximo destino. Um engano os leva a uma creche cheia de brinquedos, onde precisam se adaptar a uma nova rotina e encontrar uma forma de permanecer juntos.' WHERE titulo='Toy Story 3';
UPDATE filmes SET ano=2002, diretor='Carlos Saldanha, Chris Wedge', classificacao='PG', nota_imdb=7.5, sinopse='No início de uma era glacial, o mamute Manny, a preguiça Sid e o tigre Diego acabam responsáveis por conduzir um bebê humano de volta à sua família. A jornada atravessa paisagens perigosas e transforma a cooperação entre companheiros muito diferentes em uma amizade improvável.' WHERE titulo='A Era do Gelo';
UPDATE filmes SET ano=2001, diretor='Peter Jackson', classificacao='PG-13', nota_imdb=8.9, sinopse='Frodo recebe a missão de levar um anel de poder para longe do Condado e impedir que ele volte às mãos de Sauron. Com a ajuda de companheiros de diferentes povos, ele inicia uma longa jornada pela Terra-média, enquanto forças sombrias se organizam para recuperar o objeto.' WHERE titulo='O Senhor dos Anéis: A Sociedade do Anel';
UPDATE filmes SET ano=1994, diretor='Chuck Russell', classificacao='PG-13', nota_imdb=7.0, sinopse='Stanley Ipkiss, um bancário tímido, encontra uma máscara misteriosa que transforma sua personalidade e lhe dá habilidades extraordinárias. Ao descobrir que esse poder também chama a atenção de criminosos, ele precisa equilibrar sua nova confiança com as consequências de suas escolhas.' WHERE titulo='O Máscara';